function init(){const nav=$('navigation');document.querySelectorAll('.scene').forEach((s,i)=>{nav.innerHTML+=`<button type="button" class="nav-link" id="nav${i}" onclick="goScene(${i})"><span>${String(i+1).padStart(2,'0')}</span>${safe(s.dataset.title)}</button>`});$('studentName').value=state.name;$('studentCourse').value=state.course;$('studentName').addEventListener('input',e=>{state.name=e.target.value;save()});$('studentCourse').addEventListener('input',e=>{state.course=e.target.value;save()});$('analysisA').value=state.analysisA;$('analysisB').value=state.analysisB;$('analysisProof').value=state.analysisProof;renderSymbols();renderQuiz();renderKit();renderModes();renderPromptPanels();goScene(0)}
function goScene(i){sceneIndex=Math.min(11,Math.max(0,i));document.querySelectorAll('.scene').forEach((s,j)=>s.classList.toggle('active',j===sceneIndex));document.querySelectorAll('.nav-link').forEach((b,j)=>{b.classList.toggle('active',j===sceneIndex);if(j===sceneIndex)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});$('crumb').textContent='LABORATORIO 03 / ESCENA '+String(sceneIndex+1).padStart(2,'0');$('progressbar').style.width=((sceneIndex+1)/12*100)+'%';$('progresslabel').textContent=(sceneIndex+1)+' / 12';$('pageCount').textContent='Escena '+(sceneIndex+1)+' de 12';$('prevBtn').disabled=sceneIndex===0;$('nextBtn').disabled=sceneIndex===11;if(sceneIndex===8)renderDiagram();if(sceneIndex===9)renderReview();if(sceneIndex===10)renderResults();window.scrollTo({top:0,behavior:'instant'})}
function renderSymbols(){let html='';SYMBOL_DETAILS.forEach((s,i)=>html+=`<button class="symbolbox" onclick="selectSymbol(${i})" aria-label="Explicar ${s[0]}"><div class="sym">${s[1]}</div><b>${s[0].toUpperCase()}</b></button>`);$('symcards').innerHTML=html;selectSymbol(0)}
function selectSymbol(i){symbolIdx=i;const s=SYMBOL_DETAILS[i];$('symbolDetail').innerHTML=`<span class="eyebrow">SÍMBOLO ${i+1} DE 5</span><h3>${s[1]} &nbsp; ${s[0]}</h3><p>${s[2]}</p><div class="note important"><strong>Ejemplo:</strong> ${s[3]}</div>`}
function renderQuiz(){let q=QUIZ[quizIndex], picked=state.quiz[quizIndex];$('quizPanel').innerHTML=`<div class="statusline"><span class="chip">Pregunta ${quizIndex+1} de 8</span><span class="help">${Object.keys(state.quiz).filter(i=>state.quiz[i]===QUIZ[i][2]).length} aciertos</span></div><div class="meter" style="margin:15px 0"><div style="width:${(quizIndex+1)/8*100}%"></div></div><h3>${safe(q[0])}</h3><div class="options">${q[1].map((a,i)=>`<label class="option"><input type="radio" name="quizopt" value="${i}" ${picked===i?'checked':''} onchange="pickQuiz(${i})"><span>${safe(a)}</span></label>`).join('')}</div>${picked===undefined?'':picked===q[2]?`<div class="feedback">✓ Correcto. ${safe(q[3])}</div>`:`<div class="feedback bad">Revisa tu elección. Piensa qué elemento sigue el cursograma y qué ocurre durante la actividad. Puedes seleccionar otra alternativa.</div>`}<div class="btnrow"><button class="btn outline" ${quizIndex===0?'disabled':''} onclick="quizIndex--;renderQuiz()">← Anterior</button><button class="btn" ${picked===undefined?'disabled':''} onclick="if(quizIndex<7){quizIndex++;renderQuiz()}else{quizIndex=0;renderQuiz()}">${quizIndex===7?'Revisar desde el inicio':'Siguiente →'}</button><button class="btn tiny outline" onclick="state.quiz={};quizIndex=0;save();renderQuiz()">Reiniciar cuestionario</button></div>`}
function pickQuiz(i){state.quiz[quizIndex]=i;save();renderQuiz()}
function renderKitOriginal(){const r=state.kitRows;const n=r.length;const next=KIT[n];$('kitControls').innerHTML=n===KIT.length?`<span class="chip">Práctica completada</span><h3>¡Tu kit está listo!</h3><p>Ahora puedes pasar al caso empresarial. Resumen: 2 operaciones, 2 inspecciones, 2 transportes, una espera y un almacenaje.</p><button class="btn outline" onclick="state.kitRows=[];save();renderKit()">Repetir el ejemplo</button>`:`<span class="chip">Actividad ${n+1} de 8</span><h3>${safe(next.txt)}</h3><p>Tiempo: ${fmt(next.min)} min · Distancia: ${next.met===null?'No aplica':next.met+' m'}</p><div class="field"><label for="kitType">¿Qué símbolo representa esta actividad?</label><select id="kitType" onchange="kitCheck()"><option value="">Seleccionar símbolo</option>${TYPES.map(t=>`<option value="${t}">${SYMBOLS[TYPES.indexOf(t)]} ${t}</option>`).join('')}</select></div><button id="kitAdd" class="btn" disabled onclick="addKit()">Agregar al registro</button><div id="kitHint" aria-live="polite"></div>`;
$('kitTable').innerHTML=`<p class="help">Los puntos aparecen en su columna y la línea los une automáticamente en orden. Desliza horizontalmente la tabla si estás en un teléfono.</p><div class="diagram" id="kitChart"><svg class="connector-svg"></svg><table><colgroup><col style="width:34px"><col style="width:34%"><col style="width:39px"><col style="width:39px"><col span="5" style="width:34px"></colgroup><thead><tr><th>N.º</th><th>Actividad</th><th>m</th><th>min</th>${SYMBOLS.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${r.map((id,i)=>{let a=card(id);return `<tr><td>${i+1}</td><td>${safe(a.txt)}</td><td>${a.met===null?'—':a.met}</td><td>${a.min===null?'—':a.min}</td>${TYPES.map(t=>`<td class="symbol-cell">${a.type===t?'<span class="point"></span>':''}</td>`).join('')}</tr>`}).join('')||'<tr><td colspan="9">Aquí se dibujará el cursograma. Clasifica la primera actividad.</td></tr>'}</tbody></table></div><div class="help" style="margin-top:10px">${r.length} actividades · ${r.reduce((s,id)=>s+(card(id).min||0),0)} min conocidos · ${r.reduce((s,id)=>s+(card(id).met||0),0)} m registrados.</div>`;requestAnimationFrame(drawKitConnectors)}
function drawKitConnectors(){const el=$('kitChart');if(!el)return;const svg=el.querySelector('svg.connector-svg'),points=[...el.querySelectorAll('.point')],rect=el.getBoundingClientRect(),w=el.scrollWidth,h=el.scrollHeight;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.style.width=w+'px';svg.style.height=h+'px';const coords=points.map(p=>{const q=p.getBoundingClientRect();return {x:q.left-rect.left+el.scrollLeft+q.width/2,y:q.top-rect.top+el.scrollTop+q.height/2}});svg.innerHTML=coords.slice(1).map((p,i)=>`<line x1="${coords[i].x}" y1="${coords[i].y}" x2="${p.x}" y2="${p.y}" stroke="#176B80" stroke-width="2.5"/>`).join('')}
function kitCheck(){const val=$('kitType').value;const correct=KIT[state.kitRows.length].type;$('kitAdd').disabled=val!==correct;$('kitHint').innerHTML=val&&val!==correct?'<div class="feedback bad">Pista: piensa si la acción transforma, traslada, revisa, espera o guarda el producto.</div>':val===correct?'<div class="feedback">✓ Bien clasificada. Agrégala a la tabla.</div>':''}
function addKit(){state.kitRows.push(KIT[state.kitRows.length].id);save();renderKit()}
function renderModes(){$('modeSelector').innerHTML=Object.entries(MODE_DATA).map(([m,o])=>`<button class="categorybutton ${state.mode===m?'selected':''}" onclick="setMode('${m}')"><b>${m==='material'?'◉ Material':m==='operario'?'♙ Operario':'⚙ Equipo'}</b><small>${o.n} actividades · ${m==='material'?'3 ramas':'1 registro'}</small></button>`).join('');$('modeInfo').innerHTML=`<strong>${MODE_DATA[state.mode].name}.</strong> ${MODE_DATA[state.mode].detail}`;renderPool();renderDiagram()}
function setModeOriginal(m){state.mode=m;selectedCard=null;save();renderModes();$('inlineCheck').innerHTML=''}
function renderPool(){if(!$('activityPool'))return;const pool=POOL.filter(a=>a.txt.toLocaleLowerCase('es').includes(($('poolSearch').value||'').toLocaleLowerCase('es')));const used=current().map(r=>r.id), dismissed=state.dismissed[state.mode];$('poolCount').textContent=(CARDS.length-used.length-dismissed.length)+' disponibles';$('activityPool').innerHTML=pool.map(a=>{const done=used.includes(a.id),discarded=dismissed.includes(a.id);return `<button class="activity-card ${selectedCard===a.id?'active':''} ${done||discarded?'done':''}" onclick="chooseCard('${a.id}')"><span class="num">${a.id}</span><strong>${safe(a.txt)}</strong><span class="status">${done?'Añadida':discarded?'Descartada':'Elegir'}</span></button>`}).join('');renderDecision()}
function chooseCard(id){selectedCard=id;choiceBelongs='yes';selectedSymbol='Operación';selectedBranch=branches(state.mode)[0];renderPool()}
function renderDecision(){const el=$('cardDecision');if(!selectedCard){el.innerHTML='<div class="note important">Selecciona una tarjeta. Decide si corresponde al cursograma elegido y después ubícala en el registro.</div>';return}const a=card(selectedCard),isUsed=current().some(r=>r.id===a.id),dismissed=state.dismissed[state.mode].includes(a.id);if(isUsed){el.innerHTML=`<div class="feedback">Esta actividad ya está añadida. Puedes editarla en la tabla.</div>`;return}if(dismissed){el.innerHTML=`<p><strong>${safe(a.txt)}</strong></p><button class="btn outline" onclick="restoreCard('${a.id}')">Recuperar actividad descartada</button>`;return}el.innerHTML=`<div class="dark-card"><span class="chip gold">Tarjeta elegida</span><h3>${safe(a.txt)}</h3><p>¿Pertenece al cursograma <strong>${MODE_DATA[state.mode].name}</strong>?</p></div><div class="field" style="margin-top:12px"><label for="belongs">Tu decisión</label><select id="belongs" onchange="choiceBelongs=this.value;renderDecision()"><option value="yes" ${choiceBelongs==='yes'?'selected':''}>Sí, corresponde</option><option value="no" ${choiceBelongs==='no'?'selected':''}>No, descartar</option></select></div>${choiceBelongs==='yes'?`<div class="field"><label for="classPick">Tipo de actividad</label><select id="classPick" onchange="selectedSymbol=this.value">${TYPES.map(t=>`<option value="${t}" ${selectedSymbol===t?'selected':''}>${SYMBOLS[TYPES.indexOf(t)]} ${t}</option>`).join('')}</select></div>${state.mode==='material'?`<div class="field"><label for="branchPick">Rama donde ocurre</label><select id="branchPick" onchange="selectedBranch=this.value">${branches(state.mode).map(b=>`<option value="${b}" ${selectedBranch===b?'selected':''}>${b}</option>`).join('')}</select></div>`:''}<button class="btn" onclick="addSelected()">Agregar actividad al cursograma</button>`:`<button class="btn outline" onclick="discardSelected()">Marcar como no perteneciente</button>`}<p class="help" style="margin-top:10px">La aplicación guarda tu clasificación para poder revisarla después. También puedes cambiar el orden con las flechas de la tabla.</p>`}
function addSelected(){if(!selectedCard)return;const mode=state.mode;if(current().some(r=>r.id===selectedCard))return;state.rows[mode].push({id:selectedCard,type:($('classPick')||{}).value||selectedSymbol,branch:mode==='material'?($('branchPick')||{}).value:branches(mode)[0]});state.dismissed[mode]=state.dismissed[mode].filter(x=>x!==selectedCard);selectedCard=null;save();renderPool();renderDiagram();$('inlineCheck').innerHTML=''}
function discardSelected(){if(!selectedCard)return;const id=selectedCard;if(!state.dismissed[state.mode].includes(id))state.dismissed[state.mode].push(id);selectedCard=null;save();renderPool()}
function restoreCard(id){state.dismissed[state.mode]=state.dismissed[state.mode].filter(x=>x!==id);selectedCard=id;save();renderPool()}
function confirmReset(){if(confirm('¿Reiniciar las actividades de este cursograma? Se conservarán los otros retos y el nombre del estudiante.')){state.rows[state.mode]=[];state.dismissed[state.mode]=[];selectedCard=null;save();renderModes();$('inlineCheck').innerHTML=''}}
function moveActivity(i,dir){const rows=current();const b=rows[i].branch;const peer=[];rows.forEach((r,j)=>{if(r.branch===b)peer.push(j)});const pos=peer.indexOf(i),target=peer[pos+dir];if(target===undefined)return;[rows[i],rows[target]]=[rows[target],rows[i]];save();renderDiagram()}
function editActivity(i,val){current()[i].type=val;save();renderDiagram()}
function editBranch(i,val){current()[i].branch=val;save();renderDiagram()}
function removeActivity(i){current().splice(i,1);save();renderPool();renderDiagram()}
function renderDiagram(){if(!$('analysisDiagram'))return;const rows=current(),groups=branches(state.mode);$('diagramCount').textContent=rows.length+' / '+MODE_DATA[state.mode].n+' actividades';let html='';groups.forEach((b,bi)=>{let items=rows.map((r,i)=>({...r,orig:i})).filter(r=>r.branch===b);html+=`<div class="branch-title">${b==='Común'?'Ensamble, acabado y almacén':b==='Capellada'?'Rama 1 · Capellada':b==='Suela'?'Rama 2 · Suela':b} <span class="count">${items.length} filas</span></div><div class="diagram" id="chart-${bi}"><svg class="connector-svg"></svg><table><colgroup><col style="width:32px"><col style="width:29%"><col style="width:38px"><col style="width:40px"><col span="5" style="width:33px"><col style="width:75px"></colgroup><thead><tr><th>N.º</th><th>Descripción</th><th>m</th><th>min</th><th>○</th><th>→</th><th>□</th><th>D</th><th>▽</th><th>Orden</th></tr></thead><tbody>${items.map((r,i)=>{let a=card(r.id),idtype=TYPES.indexOf(r.type);return `<tr><td>${i+1}</td><td class="desc"><span title="${safe(a.id)}">${safe(a.txt)}</span><select aria-label="Cambiar símbolo" class="control no-print" style="margin-top:5px;font-size:10px;padding:4px" onchange="editActivity(${r.orig},this.value)">${TYPES.map(t=>`<option ${r.type===t?'selected':''}>${t}</option>`).join('')}</select>${state.mode==='material'?`<select aria-label="Cambiar rama" class="control no-print" style="margin-top:4px;font-size:10px;padding:4px" onchange="editBranch(${r.orig},this.value)">${groups.map(x=>`<option ${b===x?'selected':''}>${x}</option>`).join('')}</select>`:''}</td><td>${a.met===null?'—':a.met}</td><td>${a.min===null?'—':a.min}</td>${TYPES.map((t,j)=>`<td class="symbol-cell">${idtype===j?`<span class="point" data-row="${i}" data-branch="${bi}" data-col="${j}"></span>`:''}</td>`).join('')}<td><div class="table-operations no-print"><button title="Subir" ${i===0?'disabled':''} onclick="moveActivity(${r.orig},-1)">↑</button><button title="Bajar" ${i===items.length-1?'disabled':''} onclick="moveActivity(${r.orig},1)">↓</button><button title="Eliminar" onclick="removeActivity(${r.orig})">×</button></div></td></tr>`}).join('')||'<tr><td colspan="10">Aún no hay actividades registradas en esta rama.</td></tr>'}</tbody></table></div>`;if(state.mode==='material'&&bi===1)html+=`<div class="note important" style="font-size:11px">Capellada y suela trabajan simultáneamente. Su confluencia ocurre antes de aplicar el adhesivo; no conectes sus recorridos como una sola secuencia.</div>`});$('analysisDiagram').innerHTML=html+`<div class="grid3" style="margin-top:12px">${[['Actividades',rows.length],['Tiempo registrado',rows.reduce((s,r)=>s+(card(r.id).min||0),0)+' min'],['Distancia',rows.reduce((s,r)=>s+(card(r.id).met||0),0)+' m']].map(x=>`<div class="metric"><b>${x[1]}</b><small>${x[0]}</small></div>`).join('')}</div>`;requestAnimationFrame(drawConnectors)}
function drawConnectors(){branches(state.mode).forEach((b,i)=>{const el=$('chart-'+i);if(!el)return;const svg=el.querySelector('svg.connector-svg');const points=[...el.querySelectorAll('.point')];const h=el.scrollHeight,w=el.scrollWidth;svg.setAttribute('width',w);svg.setAttribute('height',h);svg.style.width=w+'px';svg.style.height=h+'px';svg.setAttribute('viewBox',`0 0 ${w} ${h}`);let centers=points.map(p=>{let r=p.getBoundingClientRect(),pr=el.getBoundingClientRect();return {x:r.left-pr.left+el.scrollLeft+r.width/2,y:r.top-pr.top+el.scrollTop+r.height/2}});svg.innerHTML=centers.slice(1).map((p,j)=>`<line x1="${centers[j].x}" y1="${centers[j].y}" x2="${p.x}" y2="${p.y}" stroke="#176B80" stroke-width="2" stroke-linecap="round" opacity=".8"/>`).join('')})}
window.addEventListener('resize',()=>{if(sceneIndex===8)drawConnectors();if(sceneIndex===7)drawKitConnectors()});
function validate(){let issues=[];let rows=current();const expected=EXPECTED[state.mode];const used=rows.map(x=>x.id);const missing=expected.filter(id=>!used.includes(id));const extraneous=used.filter(id=>!expected.includes(id));if(missing.length)issues.push({kind:'missing',message:`Faltan ${missing.length} actividad(es) de esta perspectiva. Vuelve al caso y revisa los pasos que todavía no seleccionaste.`,hint:'Busca actividades que ocurran antes, durante o después de las que ya tienes.',ids:missing});if(extraneous.length)issues.push({kind:'unrelated',message:`Hay ${extraneous.length} actividad(es) que no corresponden al elemento que estás siguiendo.`,hint:'Pregunta: ¿lo hace la persona, le sucede al zapato o describe un estado de la máquina?',ids:extraneous});rows.forEach((r,i)=>{let a=card(r.id);if(a.type!==r.type)issues.push({kind:'symbol',message:`Fila ${i+1}: revisa el símbolo de «${a.txt}».`,hint:'¿Transforma, traslada, inspecciona, espera o almacena?',ids:[r.id]});if(branchOf(a,state.mode)!==r.branch)issues.push({kind:'branch',message:`«${a.txt}» parece ubicada en la rama incorrecta.`,hint:'Consulta la sección del caso que describe esa actividad.',ids:[r.id]})});branches(state.mode).forEach(b=>{const got=rows.filter(x=>x.branch===b&&expected.includes(x.id)).map(x=>x.id);const want=expected.filter(id=>branchOf(card(id),state.mode)===b);let prev=-1;for(let j=0;j<got.length;j++){const k=want.indexOf(got[j]);if(k<prev){issues.push({kind:'order',message:`La secuencia de ${b} no sigue el orden descrito en el caso.`,hint:`Examina cuál actividad debe ocurrir antes de «${card(got[j]).txt}».`,ids:[got[j]]});break}prev=k}});let dismissedExpected=state.dismissed[state.mode].filter(id=>expected.includes(id));if(dismissedExpected.length)issues.push({kind:'discard',message:`Descartaste ${dismissedExpected.length} actividad(es) que sí pertenecen al cursograma elegido.`,hint:'Recupera esas tarjetas desde el banco y vuelve a evaluarlas.',ids:dismissedExpected});return {issues,missing,extraneous,complete:issues.length===0,count:rows.length}}
function reviewCurrent(inline){const r=validate();if(inline){$('inlineCheck').innerHTML=r.complete?'<div class="feedback">✓ Todas las comprobaciones del caso son satisfactorias. Ya puedes generar tu documento marcado como revisado.</div>':`<div class="feedback bad"><strong>Se encontraron ${r.issues.length} observaciones.</strong><br>${safe(r.issues[0].message)}<br><em>${safe(r.issues[0].hint)}</em><br><button class="btn tiny outline" style="margin-top:8px" onclick="goScene(9)">Ver todas las observaciones</button></div>`}else renderReview();return r}
function renderReview(){let r=validate(),rows=current();$('reviewSummary').innerHTML=`<div class="statusline"><span>Tipo de cursograma</span><strong>${state.mode}</strong></div><div class="statusline"><span>Actividades seleccionadas</span><strong>${rows.length} / ${MODE_DATA[state.mode].n}</strong></div><div class="statusline"><span>Faltantes</span><strong>${r.missing.length}</strong></div><div class="statusline"><span>Actividades no pertinentes</span><strong>${r.extraneous.length}</strong></div><div class="statusline"><span>Observaciones por resolver</span><strong>${r.issues.length}</strong></div><div class="feedback ${r.complete?'':'warn'}">${r.complete?'✓ Tu cursograma cumple las comprobaciones del caso académico.':'La revisión encontró aspectos por corregir. No se revelan las respuestas completas: utiliza las pistas.'}</div>`;$('reviewIssues').innerHTML=r.complete?'<div class="feedback">¡Bien hecho! La secuencia, las ramas y las clasificaciones coinciden con los datos del caso.</div>':r.issues.slice(0,20).map((x,i)=>`<div class="note ${i%2?'important':''}"><strong>${i+1}. ${safe(x.message)}</strong><br>Pista: ${safe(x.hint)}</div>`).join('')+(r.issues.length>20?`<p class="help">Hay ${r.issues.length-20} observaciones adicionales; corrige las primeras y vuelve a revisar.</p>`:'')}
function renderResults(){const rows=current(),tally=TYPES.map(t=>countBy(rows,t)),minutes=rows.reduce((s,r)=>s+(card(r.id).min||0),0),metres=rows.reduce((s,r)=>s+(card(r.id).met||0),0),unknown=rows.filter(r=>card(r.id).min===null).length;$('resultsPanel').innerHTML=`<h3>Tu registro — ${MODE_DATA[state.mode].name}</h3><div class="grid3"><div class="metric"><b>${rows.length}</b><small>Actividades añadidas</small></div><div class="metric"><b>${minutes} min</b><small>Suma de tiempos conocidos</small></div><div class="metric"><b>${metres} m</b><small>Distancia registrada</small></div></div><h3>Distribución de símbolos</h3>${TYPES.map((t,i)=>`<div class="statusline"><span>${SYMBOLS[i]} ${t}</span><strong>${tally[i]}</strong></div>`).join('')}<p class="help" style="margin-top:11px">${unknown?'Hay '+unknown+' actividad(es) sin duración determinada. No se suman como cero medido.':''} ${state.mode==='material'?'Capellada y suela comienzan simultáneamente: el tiempo transcurrido del caso completo es 86 minutos, cuando el registro es correcto; la suma de duraciones registradas es 124 minutos.':'Esta perspectiva corresponde a su propia ventana de observación; no se suma al tiempo del producto.'}</p><div class="note important">La revisión no autoriza eliminar automáticamente una actividad. Para justificar una mejora necesitas entender condiciones, controles obligatorios, seguridad y evidencia de campo.</div>`}
function saveTextOriginal(){state.analysisA=$('analysisA').value;state.analysisB=$('analysisB').value;state.analysisProof=$('analysisProof').value;save()}
function renderPromptPanels(){const order=[0,2,1];$('promptPanels').innerHTML=order.map((idx,i)=>`<div class="card prompt-card"><div class="btnrow" style="justify-content:space-between"><div><span class="eyebrow">PASO ${i+1}</span><h3>Prompt ${idx+1} · ${idx===0?'Levantamiento':idx===2?'Propuesta de mejora':'Gráfico en Draw.io'}</h3></div><button class="btn outline tiny" onclick="copyPrompt(${idx})">Copiar prompt</button></div><details><summary style="cursor:pointer;font-size:12px;color:#176b80;font-weight:800;margin-bottom:12px">Ver instrucciones completas del prompt</summary><pre class="prompt">${safe(PROMPTS[idx])}</pre></details></div>`).join('')+`<div class="card prompt-card"><div class="btnrow"><button class="btn outline" onclick="downloadSource('prompts')">⬇ Descargar los tres prompts en Word</button><button class="btn outline" onclick="downloadSource('plantilla')">⬇ Excel en blanco (.xlsx)</button></div></div>`}
async function copyPrompt(i){try{await navigator.clipboard.writeText(PROMPTS[i]);alert('Prompt copiado. Adjunta el Excel correspondiente y reemplaza los textos entre corchetes.')}catch(e){let ta=document.createElement('textarea');ta.value=PROMPTS[i];document.body.append(ta);ta.select();document.execCommand('copy');ta.remove();alert('Prompt copiado')}}
function downloadBlob(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type:type||'application/octet-stream'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
function fromBase64(b64){const raw=atob(b64),out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out}
function downloadSource(key){let x=SOURCE_FILES[key];if(!x||!x.url){alert('Recurso no disponible');return}const a=document.createElement('a');a.href=x.url;a.download=x.name;document.body.appendChild(a);a.click();a.remove()}
function studentName(){const n=(state.name||'').trim();if(!n){alert('Escribe tu nombre completo en la primera escena antes de descargar el cursograma.');goScene(0);$('studentName').focus();return null}return n}
function fileName(ext){const n=state.name.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,50);return `Laboratorio3_${state.mode}_${n}.${ext}`}
function xml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]))}
const enc=new TextEncoder();function bytes(v){return typeof v==='string'?enc.encode(v):v instanceof Uint8Array?v:new Uint8Array(v)}
function uint(n){return n>>>0}const crcTable=(()=>{let a=[];for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;a.push(uint(c))}return a})();
function crc32(data){let c=0xffffffff;for(let k=0;k<data.length;k++)c=crcTable[(c^data[k])&255]^(c>>>8);return uint(c^0xffffffff)}
function joinBytes(parts){let len=parts.reduce((s,p)=>s+p.length,0),out=new Uint8Array(len),o=0;for(let p of parts){out.set(p,o);o+=p.length}return out}
function zipFile(files){let local=[],central=[],offset=0;const DOSDATE=((2026-1980)<<9)|(10<<5)|22, DOSTIME=0;for(let f of files){let name=bytes(f.name),data=bytes(f.data),crc=crc32(data),hdr=new Uint8Array(30),v=new DataView(hdr.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x0800,true);v.setUint16(8,0,true);v.setUint16(10,DOSTIME,true);v.setUint16(12,DOSDATE,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);local.push(hdr,name,data);let ch=new Uint8Array(46),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x0800,true);cv.setUint16(10,0,true);cv.setUint16(12,DOSTIME,true);cv.setUint16(14,DOSDATE,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);central.push(ch,name);offset+=hdr.length+name.length+data.length}let cent=joinBytes(central),end=new Uint8Array(22),dv=new DataView(end.buffer);dv.setUint32(0,0x06054b50,true);dv.setUint16(8,files.length,true);dv.setUint16(10,files.length,true);dv.setUint32(12,cent.length,true);dv.setUint32(16,offset,true);return joinBytes([...local,cent,end])}
function chartSVG(){const groups=branches(state.mode),rows=current(),gw=state.mode==='material'?3:1,W=state.mode==='material'?1100:600;let maxRows=Math.max(1,...groups.map(b=>rows.filter(r=>r.branch===b).length)),H=160+maxRows*56;let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}"><rect width="100%" height="100%" fill="#ffffff"/><rect width="100%" height="80" fill="#112A46"/><text x="25" y="32" font-family="Arial" font-size="19" font-weight="bold" fill="white">CURSOGRAMA ANALÍTICO — ${xml(MODE_DATA[state.mode].name)}</text><text x="25" y="55" font-family="Arial" font-size="13" fill="#e5eef2">Estudiante: ${xml(state.name||'Sin identificar')} | Método Actual | Mg. Vicky Ruiz</text>`;groups.forEach((b,g)=>{let list=rows.filter(r=>r.branch===b),colW=W/gw,x0=g*colW,center=x0+48;svg+=`<rect x="${x0+10}" y="94" width="${colW-20}" height="28" rx="6" fill="#edf4f5"/><text x="${x0+20}" y="113" font-family="Arial" font-size="14" font-weight="bold" fill="#112A46">${xml(b)}</text>`;list.forEach((r,i)=>{let a=card(r.id),y=150+i*56;let t=SYMBOLS[TYPES.indexOf(r.type)];if(i)svg+=`<line x1="${center}" y1="${y-38}" x2="${center}" y2="${y-14}" stroke="#176B80" stroke-width="2.5"/>`;let sh=t==='○'?`<circle cx="${center}" cy="${y}" r="11" fill="white" stroke="#176B80" stroke-width="2.5"/>`:t==='□'?`<rect x="${center-10}" y="${y-10}" width="20" height="20" fill="white" stroke="#176B80" stroke-width="2.5"/>`:t==='→'?`<path d="M ${center-13} ${y} H${center+10} m-7 -8 l8 8 -8 8" stroke="#176B80" stroke-width="2.5" fill="none"/>`:t==='D'?`<path d="M${center-10} ${y-10} H${center} A10 10 0 0 1 ${center} ${y+10} H${center-10}Z" fill="white" stroke="#176B80" stroke-width="2.5"/>`:`<path d="M${center-12} ${y-9} H${center+12} L${center} ${y+12}Z" fill="white" stroke="#176B80" stroke-width="2.5"/>`;svg+=sh;let text=a.txt.length>36?a.txt.slice(0,35)+'…':a.txt;svg+=`<text x="${center+24}" y="${y-3}" font-family="Arial" font-size="${gw===3?11:13}" fill="#303A46">${xml(text)}</text><text x="${center+24}" y="${y+13}" font-family="Arial" font-size="10" fill="#607384">${a.min===null?'sin tiempo definido':a.min+' min'}${a.met===null?'':' · '+a.met+' m'}</text>`})});if(state.mode==='material')svg+=`<text x="550" y="${H-22}" text-anchor="middle" font-family="Arial" font-size="12" fill="#176B80">Capellada + suela confluyen antes del ensamble · Los trabajos paralelos no se suman como ciclo transcurrido</text>`;svg+='</svg>';return svg}
async function imagePNG(){let s=chartSVG(),svgBlob=new Blob([s],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(svgBlob);try{const im=new Image();im.src=url;await new Promise((res,rej)=>{im.onload=res;im.onerror=rej});const canvas=document.createElement('canvas');canvas.width=im.naturalWidth;canvas.height=im.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(im,0,0);const blob=await new Promise(res=>canvas.toBlob(res,'image/png'));return new Uint8Array(await blob.arrayBuffer())}finally{URL.revokeObjectURL(url)}}
async function exportPNG(){if(!studentName())return;try{downloadBlob(await imagePNG(),fileName('png'),'image/png')}catch(e){alert('No fue posible crear la imagen en este navegador. Puedes descargar el archivo Draw.io.') }}
function drawioXml(){const b=branches(state.mode),rows=current();let c=2,items=[],edges=[];const mx=id=>xml(id);for(let branchIndex=0;branchIndex<b.length;branchIndex++){let prev=null;rows.filter(r=>r.branch===b[branchIndex]).forEach((r,i)=>{let a=card(r.id),id='node'+c++,x=20+branchIndex*345,y=70+i*66,shape=r.type==='Operación'?'ellipse':r.type==='Inspección'?'rectangle':r.type==='Transporte'?'rightArrow':r.type==='Espera'?'delay':'triangle',rotation=r.type==='Almacenaje'?180:0;items.push(`<mxCell id="${id}" value="${mx(a.txt)} (${a.min===null?'sin tiempo':a.min+' min'})" style="shape=${shape};rotation=${rotation};whiteSpace=wrap;html=0;fillColor=#edf4f5;strokeColor=#176B80;fontColor=#112A46;align=center;verticalAlign=middle;fontSize=11;" vertex="1" parent="1"><mxGeometry x="${x}" y="${y}" width="290" height="48" as="geometry"/></mxCell>`);if(prev){edges.push(`<mxCell id="edge${c++}" style="edgeStyle=orthogonalEdgeStyle;rounded=0;endArrow=classic;html=1;strokeColor=#176B80;" edge="1" parent="1" source="${prev}" target="${id}"><mxGeometry relative="1" as="geometry"/></mxCell>`)}prev=id})}return `<?xml version="1.0" encoding="UTF-8"?><mxfile host="app.diagrams.net" modified="2026-10-22T00:00:00Z" agent="AulaEscena" version="1"><diagram name="${mx(MODE_DATA[state.mode].name)}"><mxGraphModel><root><mxCell id="0"/><mxCell id="1" parent="0"/>${items.join('')}${edges.join('')}</root></mxGraphModel></diagram></mxfile>`}
