function xCell(r,c,v,style=0,formula=false){if(v===undefined||v===null)return '';const col=n=>{let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s};let ref=col(c)+(r+1);if(formula){const f=typeof v==='object'?v.formula:v;const cached=typeof v==='object'?(v.cached||0):0;return `<c r="${ref}" s="${style}"><f>${xml(String(f).replace(/^=/,''))}</f><v>${cached}</v></c>`};if(typeof v==='number')return `<c r="${ref}" s="${style}"><v>${v}</v></c>`;return `<c r="${ref}" s="${style}" t="inlineStr"><is><t>${xml(v)}</t></is></c>`}
function worksheetXml(type){let rows=[],merges=[];const name=type==='actual'?'Actual':type==='propuesto'?'Propuesto':type==='mejoras'?'Mejoras':'Gráfico';function put(row,c,v,style=0,formula=false){rows[row]??=[];rows[row].push(xCell(row,c,v,style,formula))};put(0,0,'CURSOGRAMA ANALÍTICO · MÉTODOS Y TIEMPOS',1);merges.push('A1:M1');put(2,0,'Estudiante');put(2,2,state.name);put(3,0,'Proceso');put(3,2,'Fabricación de un zapato de cuero');put(4,0,'Tipo');put(4,2,MODE_DATA[state.mode].name);put(5,0,'Método');put(5,2,name);put(6,0,'Docente');put(6,2,'Mg. Vicky Ruiz');if(type==='actual'||type==='propuesto'){let heads=['Rama','Perspectiva','N.º','Descripción','', 'Cantidad','Metros','Segundos','○ Operación','→ Transporte','□ Inspección','D Espera','▽ Almacenaje'];heads.forEach((x,j)=>{if(x)put(16,j,x,2)});let data=type==='actual'?current():[],last=Math.max(42,17+data.length);data.forEach((r,i)=>{let a=card(r.id),z=17+i;put(z,0,r.branch,4);put(z,1,state.mode,4);put(z,2,i+1,4);put(z,3,a.txt,4);put(z,5,1,4);if(a.met!==null)put(z,6,a.met,4);if(a.min!==null)put(z,7,a.min*60,4);put(z,8+TYPES.indexOf(r.type),'•',5);merges.push(`D${z+1}:E${z+1}`)});let totalRow=last+3;put(totalRow,0,'TOTAL',3);put(totalRow,6,{formula:`=SUM(G18:G${last+1})`,cached:type==='actual'?data.reduce((v,r)=>v+(card(r.id).met||0),0):0},3,true);put(totalRow,7,{formula:`=SUM(H18:H${last+1})`,cached:type==='actual'?data.reduce((v,r)=>v+(card(r.id).min||0)*60,0):0},3,true);for(let j=8;j<=12;j++){const L='IJKLM'[j-8];put(totalRow,j,{formula:`=COUNTIF(${L}18:${L}${last+1},"•")`,cached:type==='actual'?countBy(data,TYPES[j-8]):0},3,true)}put(totalRow+2,0,'Nota: celdas sin tiempo determinado quedan vacías; no se consideran tiempo medido.');merges.push(`A${totalRow+3}:M${totalRow+3}`)}else if(type==='mejoras'){const heads=['Actividad actual','Decisión','Herramienta','Justificación y evidencia'];heads.forEach((x,j)=>put(8,j,x,2));let notes=[state.analysisA,state.analysisB].filter(x=>x.trim());notes.forEach((n,i)=>put(9+i,3,n,4));put(14,0,'Datos por medir');put(14,3,state.analysisProof,4);merges.push('D15:H15')}else{put(8,0,'El gráfico del cursograma se incluye como imagen y puede descargarse adicionalmente en PNG y Draw.io.');merges.push('A9:M9')}let rowXML=Object.keys(rows).map(k=>`<row r="${Number(k)+1}">${rows[k].join('')}</row>`).join('');let cols=`<cols><col min="1" max="1" width="17" customWidth="1"/><col min="2" max="2" width="18" customWidth="1"/><col min="3" max="3" width="9" customWidth="1"/><col min="4" max="4" width="44" customWidth="1"/><col min="5" max="5" width="5" customWidth="1"/><col min="6" max="8" width="12" customWidth="1"/><col min="9" max="13" width="15" customWidth="1"/></cols>`;return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheetViews><sheetView workbookViewId="0"/></sheetViews><sheetFormatPr defaultRowHeight="19"/>${cols}<sheetData>${rowXML}</sheetData>${merges.length?`<mergeCells count="${merges.length}">${merges.map(x=>`<mergeCell ref="${x}"/>`).join('')}</mergeCells>`:''}${type==='grafico'?'<drawing r:id="rId1"/>':''}</worksheet>`}
