async function exportDocx(){if(!studentName())return;try{$('exportMessage').textContent='Preparando Word...';downloadBlob(await buildDocx(),fileName('docx'),'application/vnd.openxmlformats-officedocument.wordprocessingml.document');$('exportMessage').textContent='Word generado. Incluye identificación, tablas, gráfico y análisis.'}catch(e){console.error(e);$('exportMessage').textContent='Error al preparar Word: '+e.message}}
function printReport(){if(!studentName())return;let r=current(),types=TYPES.map(t=>`${t}: ${countBy(r,t)}`).join(' · '),html=`<div class="report-h"><h1>CURSOGRAMA ANALÍTICO</h1><p>${safe(MODE_DATA[state.mode].name)} — Método Actual</p></div><p><strong>Estudiante:</strong> ${safe(state.name)} &nbsp; <strong>Grupo:</strong> ${safe(state.course)}</p><p><strong>Proceso:</strong> fabricación de un zapato de cuero · Calzados del Caribe S.A.S. (caso ficticio)</p><p><strong>Docente:</strong> Mg. Vicky Ruiz &nbsp; <strong>Estado:</strong> ${validate().complete?'Revisado':'Borrador pendiente de revisión'}</p>`;branches(state.mode).forEach(b=>{let a=r.filter(x=>x.branch===b);html+=`<h3>${safe(b)}</h3><table><thead><tr><th>N°</th><th>Actividad</th><th>m</th><th>s</th>${SYMBOLS.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${a.map((x,i)=>{let v=card(x.id);return `<tr><td>${i+1}</td><td>${safe(v.txt)}</td><td>${v.met??'—'}</td><td>${v.min===null?'ND':v.min*60}</td>${TYPES.map(t=>`<td>${x.type===t?'•':''}</td>`).join('')}</tr>`}).join('')}</tbody></table>`});html+=`<h3>Resumen</h3><p>${types}</p><p>Tiempo conocido registrado: ${r.reduce((s,v)=>s+(card(v.id).min||0),0)} min · Distancia: ${r.reduce((s,v)=>s+(card(v.id).met||0),0)} m.</p><div class="subsection"><h3>Gráfico del cursograma</h3>${chartSVG()}</div><div class="subsection"><h3>Análisis del estudiante</h3><p>${safe(state.analysisA||'Pendiente')}</p><p>${safe(state.analysisB||'Pendiente')}</p><p>${safe(state.analysisProof||'Pendiente')}</p><p>Mg. Vicky Ruiz</p></div>`;$('printSheet').innerHTML=html;window.print()}
